const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-0.819876, 53.083908]);
  const geometry = point.buffer(5000); // 5km radius

  const date1 = '2024-01-04';
  const date2 = '2022-01-05';

  // Cloud masking function for Sentinel-2
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                 .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // Function to get and process water extent for a date
  function getWaterExtent(date) {
    const collection = ee.ImageCollection('COPERNICUS/S2_SR')
      .filterBounds(geometry)
      .filterDate(date, ee.Date(date).advance(1, 'day'))
      .map(maskS2clouds);

    const size = collection.size().getInfo();
    if (size === 0) return {count: 0, images: 0};

    const image = collection.first();

    // Calculate NDWI for water detection
    const ndwi = image.normalizedDifference(['B3', 'B8']).rename('NDWI');

    // Water mask (NDWI > 0 typically indicates water)
    const waterMask = ndwi.gt(0);

    // Count water pixels
    const waterCount = waterMask.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: 20,
      maxPixels: 1e9
    }).get('NDWI').getInfo();

    return {count: waterCount || 0, images: size};
  }

  // 2. Data Acquisition & Processing
  const water2024 = getWaterExtent(date1);
  const water2022 = getWaterExtent(date2);

  // 3. Output stats
  console.log(`2024-01-04: Images=${water2024.images}, WaterPixels=${water2024.count}`);
  console.log(`2022-01-05: Images=${water2022.images}, WaterPixels=${water2022.count}`);

  // 4. Check for empty collections
  if (water2024.images === 0 || water2022.images === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 5. Check for no valid pixels
  if (water2024.count === 0 || water2022.count === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 6. Check for calculation failure
  if (water2024.count === null || water2022.count === null || 
      isNaN(water2024.count) || isNaN(water2022.count)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // 7. Compare water extents
  if (water2024.count > water2022.count) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
